#!/usr/bin/env python3
"""Narrow full-scope correctness adoption, contribution discharge and discovery dispatch."""
import datetime,importlib.util,json,stat,subprocess,sys,hashlib
from pathlib import Path
O=Path(__file__).resolve().parent;B=O.parents[1];P=B.parents[2]
sp=importlib.util.spec_from_file_location('replay',O/'replay.py');h=importlib.util.module_from_spec(sp);sp.loader.exec_module(h)
def read(p):return json.loads(p.read_text())
def git(*args):return subprocess.check_output(['git',*args],cwd=P)
def main(mode):
    base=read(O/'integration-baseline.json');head=base['head'];prefix=git('rev-parse','--show-prefix').decode().strip();assert prefix=='openai-proof-research/'
    if mode!='committed':assert git('rev-parse','HEAD').decode().strip()==head
    rel=(B/'tasks.json').relative_to(P).as_posix();old=json.loads(git('show',head+':'+prefix+rel));new=read(B/'tasks.json');assert len(old['tasks'])==586 and len(new['tasks'])==587 and [i for i in range(586)if old['tasks'][i]!=new['tasks'][i]]==[580,582,583]
    assert {k for k in old if old[k]!=new[k]}=={'tasks','last_parent_progress','current_work_snapshot'} and new['newAccepted']==19 and new['remaining']==1 and new['target']==20 and new['latestAcceptance']==old['latestAcceptance']=='R041'
    s0=old['current_work_snapshot'];s=new['current_work_snapshot'];assert {k for k in s0 if s0[k]!=s[k]}=={'observed_utc','note','status_note','t3_current_confirmed_running','fresh_discovery_current','t3_dispatch_observations','analytic_r166_reviews','analytic_r166_contribution_adoption'} and set(s)-set(s0)=={'analytic_r166_correctness_adoption','structural175_prospective_isolation'} and not set(s0)-set(s)
    assert s['t3_dispatch_observations'][:-1]==s0['t3_dispatch_observations'] and not s['pending_terminal_intakes_20261021'] and not s['t3_last_polled_running'] and s['fresh_discovery_current']==['fresh-arithmetic-discovery-r137','fresh-analytic-discovery-r167','fresh-structural-discovery-r175'] and s['t3_current_confirmed_running']==[new['tasks'][i]['taskId']for i in [584,585,586]]
    for i,n in [(582,'task-status.json'),(586,'structural-r175-dispatch.json')]:assert all(new['tasks'][i][k]==v for k,v in read(O/n)['structuredContent'].items())
    adoption=read(O/'adoption.json');assert s['analytic_r166_correctness_adoption']==adoption and adoption['review_verdict']=='PASS' and adoption['contribution']=='TECHNICAL' and adoption['contribution_correctness_condition']=='DISCHARGED' and not adoption['accepted'] and adoption['count_change']==0 and h.sha(O/'assessment.md')==adoption['parent_assessment_sha256'] and h.sha(B/'analytic-r166-proof-r1/REVIEW.md')==adoption['review_sha256']
    assert new['tasks'][580]['correctness']=='PASS' and new['tasks'][580]['contribution']=='TECHNICAL' and new['tasks'][580]['parent_disposition']=='FULL_SCOPE_CLOSED_CORRECTNESS_PASS_CONTRIBUTION_TECHNICAL' and new['tasks'][583]['correctness_condition']=='DISCHARGED' and s['analytic_r166_contribution_adoption']['correctness_condition']=='DISCHARGED'
    t=new['tasks'][586];assert t['providerInstanceId']=='codex' and t['model']=='gpt-6-astra' and {x['id']:x['value']for x in t['options']}=={'reasoningEffort':'high','serviceTier':'default'} and t['status']=='running' and not t['hasPendingChildRuns'] and not t['hasPendingQuestion'] and t['pendingApproval'] is None and not t['accepted'] and t['count_change']==0 and t['source_family_navigation']==178
    pro=read(O/'prospective-isolation.json');assert pro['before_structural175_root_and_brief'] and pro['both_original_initial_guards_cover_entire_structural175_namespace'] and pro['no_live_peer_body_status_activity_read_poll_or_steer']
    for e in pro['existing_active_peer_original_initial_briefs']:
        peer=old['tasks'][e['task_index']];assert e['taskId']==peer['taskId'] and h.sha(B/e['brief'])==e['sha256']==peer['brief_sha256'] and e['literal_existing_exclusion'].encode()in(B/e['brief']).read_bytes()
    marker='--- COMPLETE ORIGINAL STANDING BRIEF (two obsolete lines overridden above) ---\n';text=(B/t['brief']).read_text();suffix=text.split(marker)[1];assert len(suffix.encode())==5570 and suffix==(B/'expanded-target-2026-10-17/fresh-analytic-r167-brief.txt').read_text().split(marker)[1] and h.sha(B/t['brief'])==t['brief_sha256']==pro['new_brief']['sha256']==adoption['new_brief_sha256'] and 'DISCHARGED'in text
    nav=read(O/'private/source178-navigation.json');tree=read(P/'sources/preprints-tree.json');lookup={e['path']:e for e in tree['tree']};assert len(tree['tree'])==13223 and not tree['truncated'] and h.sha(P/'sources/preprints-tree.json')=='eeecc1da49aa02877d137c4fb90339aca460ec27718b623916368bc08dc5e09b' and len(nav['entries'])==13 and all(lookup[e['path']]==e for e in nav['entries']) and any(e['path']in text for e in nav['entries'])
    n=read(O/'private/title-navigation.json');assert n['numeric_range']==[175,190] and n['title_only'] and not n['whole_map_decoded'] and len(n['families_selected'])==1 and n['families_selected'][0]['family']==178 and h.sha(P/'sources/CONTENTS.md')==n['catalogue_sha256'] and h.sha(O/'private/catalogue-178.md')==n['families_selected'][0]['selected_sha256']
    obs=read(O/'observed-root.json');root=B/'analytic-r166-proof-r1';replay=read(O/'replay.json');assert h.snap(root)==obs['root'] and stat.S_IMODE(root.stat().st_mode)==obs['root_mode'] and all(h.sha(P/p)==v for p,v in replay['stable_named_originals'].items())
    for e in replay['bounded_original_extents']:
        with (P/e['path']).open('rb')as f:f.seek(e['start']);data=f.read(e['end']-e['start'])
        assert hashlib.sha256(data).hexdigest()==e['sha256']
    ar=B/'discovery-arithmetic-r136-parent';an=B/'discovery-analytic-r161-parent';a166=B/'discovery-analytic-r166-parent'
    for r,p in [('fresh-arithmetic-discovery-r136',ar),('arithmetic-r136-proof-r1',ar/'proof-r1-adoption'),('arithmetic-r136-contribution-r1',ar/'contribution-r1-adoption'),('arithmetic-r136-repair-r1',ar/'repair-r1-adoption'),('fresh-analytic-discovery-r161',an),('analytic-r161-proof-r1',an/'proof-r1-adoption'),('analytic-r161-contribution-r1',an/'contribution-r1-adoption'),('fresh-analytic-discovery-r166',a166),('analytic-r166-contribution-r1',a166/'contribution-r1-adoption')]:assert h.snap(B/r)==read(p/'observed-root.json')['root']
    assert all(h.sha(P/p)==v for p,v in base['protected_unrelated_sha256'].items()) and (P/'frontier/NEW-TEN-2026-10-14.md').read_bytes().startswith(git('show',head+':'+prefix+'frontier/NEW-TEN-2026-10-14.md'))
    files=read(O/'staging-allowlist.json')['files'];assert len(files)==len(set(files))==17 and len([p for p in files if'/analytic-r166-proof-r1/'in p])==3 and not any('/private/'in p or '/controls/'in p or '/fresh-structural-discovery-r175/'in p or p.endswith(('/observed-root.json','/replay.json'))for p in files)
    expected={prefix+p for p in files};protected={prefix+p for p in base['protected_unrelated_sha256']}
    if mode=='prestage':
        assert not git('diff','--cached','--name-only') and set(git('diff','--name-only').decode().splitlines())==protected|{prefix+rel,prefix+'frontier/NEW-TEN-2026-10-14.md'}
        (O/'integration-validation.json').write_text(json.dumps({'observed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'baseline_head':head,'changed_existing_task_indices':[580,582,583],'new_task_indices':[586],'other_tasks_and_snapshot_fields_unchanged':True,'entire_unchanged_correctness':'PASS','entire_unchanged_contribution':'TECHNICAL','contribution_condition':'DISCHARGED','no_acceptance_count_repair_retry_or_downstream_gates':True,'source178_one_body_thirteen_canonical_metadata_objects':True,'both_initial_guards_precede_new_root_brief_dispatch':True,'complete_original5570byte_suffix_preserved':True,'sealed_author_both_reviews_and_prior_closed_roots_unchanged':True,'no_live_peer_body_status_activity_read_poll_or_steer':True,'protected_bodies_named_metadata_nested_seal_local_unstaged':True,'journal_prefix_and_protected_unrelated_files_unchanged':True,'explicit_allowed_paths':17,'newAccepted':19,'remaining':1,'publication':'STOPPED'},indent=2)+'\n')
    else:
        if mode=='staged':actual=set(git('diff','--cached','--name-only').decode().splitlines());obj=':';subprocess.run(['git','diff','--cached','--check'],cwd=P,check=True)
        else:assert mode=='committed' and not git('diff','--cached','--name-only') and git('rev-parse','HEAD^').decode().strip()==head;actual=set(git('diff-tree','--no-commit-id','--name-only','-r','HEAD').decode().splitlines());obj='HEAD:'
        assert actual==expected,(actual-expected,expected-actual);assert all(git('show',obj+prefix+p)==(P/p).read_bytes()for p in files) and set(git('diff','--name-only').decode().splitlines())==protected
    print(json.dumps({'phase':mode,'files':17,'tasks':587,'count':19,'sealed_roots_unchanged':True}))
if __name__=='__main__':main(sys.argv[1])
